INSERT INTO `pxl_comments` (`comment_ID`, `comment_post_ID`, `comment_author`, `comment_author_email`, `comment_author_url`, `comment_author_IP`, `comment_date`, `comment_date_gmt`, `comment_content`, `comment_karma`, `comment_approved`, `comment_agent`, `comment_type`, `comment_parent`, `user_id`) VALUES
(1, 1, 'A WordPress Commenter', 'wapuu@wordpress.example', 'https://wordpress.org/', '', '2025-11-13 06:28:12', '2025-11-13 06:28:12', 'Hi, this is a comment.\nTo get started with moderating, editing, and deleting comments, please visit the Comments screen in the dashboard.\nCommenter avatars come from <a href=\"https://gravatar.com/\">Gravatar</a>.', 0, '1', '', 'comment', 0, 0),
(2, 485, 'Oliver Williams', 'newman57@bigmir.net', '', '193.19.255.145', '2024-11-29 13:15:28', '2024-11-29 13:15:28', 'I love this theme. Sometimes it\'s difficult to work with some themes, because even if they are created with Elementor, you can\'t edit all the things with Elementor. Is not the case of Bili. All is created with Elementor and you don\'t need Elementor Pro. Definitely recommended.', 0, '1', '', 'comment', 0, 0),
(3, 485, 'David Parker', 'davidparker@bigmir.net', '', '193.19.255.145', '2024-11-29 13:16:10', '2024-11-29 13:16:10', 'They have really taken their time to work appearance of the theme, also, they have a very intereactive client assistance service.', 0, '1', '', 'comment', 2, 0),
